// 轻量级 Markdown 解析器
(function(global) {
  'use strict';

  function escapeHtml(text) {
    if (!text) return '';
    return String(text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  // 处理转义字符
  const escapeChars = [];
  function processEscapes(text) {
    return text.replace(/\\([\\`*_{}\[\]()#+\-.!~])/g, function(match, char) {
      escapeChars.push(char);
      return '\x00ESC' + (escapeChars.length - 1) + '\x00';
    });
  }

  function restoreEscapes(text) {
    return text.replace(/\x00ESC(\d+)\x00/g, function(match, index) {
      return escapeChars[parseInt(index)] || '';
    });
  }

  // 统一的行内 Markdown 解析函数
  function parseInline(text, options = {}) {
    if (!text) return '';
    
    let result = text;
    
    // 粗体 **text** 或 __text__
    result = result.replace(/\*\*([^*]+?)\*\*/g, '<strong>$1</strong>');
    result = result.replace(/__([^_]+?)__/g, '<strong>$1</strong>');
    
    // 斜体 *text* 或 _text_（避免匹配粗体）
    result = result.replace(/\*([^*\s][^*]*?[^*\s])\*/g, '<em>$1</em>');
    result = result.replace(/_([^_\s][^_]*?[^_\s])_/g, '<em>$1</em>');
    // 单字符斜体
    result = result.replace(/\*([^*\s])\*/g, '<em>$1</em>');
    result = result.replace(/_([^_\s])_/g, '<em>$1</em>');
    
    // 删除线 ~~text~~
    result = result.replace(/~~([^~]+?)~~/g, '<del>$1</del>');
    
    // 行内代码（已在前面处理，这里跳过）
    if (!options.skipCode) {
      result = result.replace(/`([^`]+)`/g, '<code>$1</code>');
    }
    
    // 链接 [text](url)
    if (!options.skipLinks) {
      result = result.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(match, text, url) {
        const trimmedUrl = url.trim().toLowerCase();
        if (/^(javascript|data|vbscript):/i.test(trimmedUrl)) {
          return '<a href="#" title="链接已禁用：不安全的协议">' + text + '</a>';
        }
        return '<a href="' + url.trim() + '" target="_blank" rel="noopener noreferrer">' + text + '</a>';
      });
    }
    
    // 图片 ![alt](src)
    if (!options.skipImages) {
      result = result.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, function(match, alt, src) {
        const trimmedSrc = src.trim().toLowerCase();
        if (/^(javascript|data|vbscript):/i.test(trimmedSrc)) {
          return '<span style="color:#999;font-style:italic">[图片已禁用：不安全的来源]</span>';
        }
        return '<img alt="' + alt + '" src="' + src.trim() + '" style="max-width:100%;" onerror="this.style.display=\'none\';this.nextElementSibling&&this.nextElementSibling.style.display=\'inline\';"><span style="display:none;color:#999;font-size:12px;">[图片加载失败]</span>';
      });
    }
    
    return result;
  }

  function parseMarkdown(text) {
    if (!text) return '';

    let html = text;
    escapeChars.length = 0; // 重置转义字符数组
    
    // 先处理转义字符
    html = processEscapes(html);

    // 先处理代码块（支持语言标识）
    const codeBlocks = [];
    html = html.replace(/```(\w*)\n?([\s\S]*?)```/g, function(match, lang, code) {
      const trimmed = code.trim();
      // 如果是 ```markdown 开头，提取内容并作为普通 markdown 处理
      if (lang.toLowerCase() === 'markdown') {
        return trimmed;
      }
      const langClass = lang ? ' class="language-' + escapeHtml(lang) + '"' : '';
      codeBlocks.push('<pre><code' + langClass + '>' + escapeHtml(trimmed) + '</code></pre>');
      return '\x00CODE' + (codeBlocks.length - 1) + '\x00';
    });

    // 处理行内代码（支持空代码 ``）
    const inlineCodes = [];
    html = html.replace(/`([^`]*)`/g, function(match, code) {
      inlineCodes.push('<code>' + escapeHtml(code) + '</code>');
      return '\x00INLINE' + (inlineCodes.length - 1) + '\x00';
    });

    // 处理表格
    const tables = [];
    html = html.replace(/((?:^\|[^\n]*\|\n)+)/gm, function(match, tableContent) {
      const lines = tableContent.trim().split('\n');
      if (lines.length < 2) return match;

      // 检查第二行是否是分隔符行 (|------|------|)
      const separatorLine = lines[1].trim();
      if (!separatorLine.match(/^\|[-:\s|]+\|$/)) return match;

      let tableHtml = '<table>';

      // 处理表头
      const headers = lines[0].split('|').map(s => s.trim()).filter(s => s);
      tableHtml += '<thead><tr>';
      headers.forEach(header => {
        tableHtml += '<th>' + parseInline(header) + '</th>';
      });
      tableHtml += '</tr></thead>';

      // 处理表身
      tableHtml += '<tbody>';
      for (let i = 2; i < lines.length; i++) {
        const cells = lines[i].split('|').map(s => s.trim()).filter(s => s);
        if (cells.length > 0) {
          tableHtml += '<tr>';
          // 确保单元格数量与表头一致
          const maxCells = Math.max(cells.length, headers.length);
          for (let j = 0; j < maxCells; j++) {
            const cell = cells[j] || '';
            tableHtml += '<td>' + parseInline(cell) + '</td>';
          }
          tableHtml += '</tr>';
        }
      }
      tableHtml += '</tbody></table>';

      tables.push(tableHtml);
      return '\x00TABLE' + (tables.length - 1) + '\x00';
    });

    // 处理标题
    html = html.replace(/^###### (.*)$/gim, '<h6>$1</h6>');
    html = html.replace(/^##### (.*)$/gim, '<h5>$1</h5>');
    html = html.replace(/^#### (.*)$/gim, '<h4>$1</h4>');
    html = html.replace(/^### (.*)$/gim, '<h3>$1</h3>');
    html = html.replace(/^## (.*)$/gim, '<h2>$1</h2>');
    html = html.replace(/^# (.*)$/gim, '<h1>$1</h1>');

    // 处理粗体和斜体
    html = html.replace(/\*\*([^*]+?)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/__([^_]+?)__/g, '<strong>$1</strong>');
    html = html.replace(/\*([^*\s][^*]*?[^*\s])\*/g, '<em>$1</em>');
    html = html.replace(/_([^_\s][^_]*?[^_\s])_/g, '<em>$1</em>');
    html = html.replace(/\*([^*\s])\*/g, '<em>$1</em>');
    html = html.replace(/_([^_\s])_/g, '<em>$1</em>');

    // 处理删除线
    html = html.replace(/~~([^~]+?)~~/g, '<del>$1</del>');

    // 处理链接（过滤危险协议）
    html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(match, text, url) {
      const trimmedUrl = url.trim().toLowerCase();
      if (/^(javascript|data|vbscript):/i.test(trimmedUrl)) {
        return '<a href="#" title="链接已禁用：不安全的协议">' + text + '</a>';
      }
      return '<a href="' + url.trim() + '" target="_blank" rel="noopener noreferrer">' + text + '</a>';
    });

    // 处理图片（过滤危险协议）
    html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, function(match, alt, src) {
      const trimmedSrc = src.trim().toLowerCase();
      if (/^(javascript|data|vbscript):/i.test(trimmedSrc)) {
        return '<span style="color:#999;font-style:italic">[图片已禁用：不安全的来源]</span>';
      }
      return '<img alt="' + alt + '" src="' + src.trim() + '" style="max-width:100%;" onerror="this.style.display=\'none\';this.nextElementSibling&&this.nextElementSibling.style.display=\'inline\';"><span style="display:none;color:#999;font-size:12px;">[图片加载失败]</span>';
    });

    // 处理独立引用块（不在列表内的）
    const blockquotes = [];
    html = html.replace(/(^>[ \t]?.+(?:\n>[ \t]?.+)*)/gm, function(match) {
      let content = match.replace(/^>[ \t]?/gm, '');
      content = parseInline(content);
      blockquotes.push('<blockquote>' + content.replace(/\n/g, '<br>') + '</blockquote>');
      return '\x00BLOCKQUOTE' + (blockquotes.length - 1) + '\x00';
    });

    // 处理列表（支持嵌套和多行内容）
    function parseLists(text) {
      const lines = text.split('\n');
      const result = [];
      const listStack = [];
      let currentLiContent = null;
      let currentLiIndent = 0;

      function isListItem(line) {
        return line.match(/^(\s*)[-*] /) || line.match(/^(\s*)\d+\. /);
      }

      // 处理列表项内的引用块
      function parseBlockquoteInLi(lines) {
        const result = [];
        let inBlockquote = false;
        let bqContent = [];

        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          const bqMatch = line.match(/^(\s*)>\s?(.*)$/);

          if (bqMatch) {
            if (!inBlockquote) {
              inBlockquote = true;
              bqContent = [];
            }
            bqContent.push(bqMatch[2]);
          } else {
            if (inBlockquote) {
              const content = parseInline(bqContent.join('<br>'));
              result.push('<blockquote>' + content + '</blockquote>');
              inBlockquote = false;
              bqContent = [];
            }
            result.push(line);
          }
        }

        if (inBlockquote && bqContent.length > 0) {
          const content = parseInline(bqContent.join('<br>'));
          result.push('<blockquote>' + content + '</blockquote>');
        }

        return result;
      }

      function flushLi() {
        if (currentLiContent !== null) {
          // 处理列表项内容中的引用块
          const processedContent = parseBlockquoteInLi(currentLiContent);
          result.push(`<li>${processedContent.join(' ')}</li>`);
          currentLiContent = null;
        }
      }

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmed = line.trim();

        // 检测列表项
        const unorderedMatch = line.match(/^(\s*)[-*] (.*)$/);
        const orderedMatch = line.match(/^(\s*)(\d+)\. (.*)$/);

        if (unorderedMatch || orderedMatch) {
          const match = unorderedMatch || orderedMatch;
          const indent = match[1].length;
          const isOrdered = !!orderedMatch;
          let content = unorderedMatch ? match[2] : match[3];

          // 确定当前列表类型
          const listType = isOrdered ? 'ol' : 'ul';

          // 先刷新之前的列表项
          flushLi();

          // 处理列表层级变化
          if (listStack.length === 0) {
            // 开始新列表
            listStack.push({ type: listType, indent: indent });
            result.push(`<${listType}>`);
          } else {
            const lastList = listStack[listStack.length - 1];

            if (indent > lastList.indent) {
              // 进入更深层级
              listStack.push({ type: listType, indent: indent });
              result.push(`<${listType}>`);
            } else if (indent < lastList.indent) {
              // 返回更浅层级
              while (listStack.length > 0 && listStack[listStack.length - 1].indent > indent) {
                flushLi();
                const closing = listStack.pop();
                result.push(`</${closing.type}>`);
              }
              // 检查是否需要切换列表类型
              const currentList = listStack[listStack.length - 1];
              if (currentList && currentList.indent === indent && currentList.type !== listType) {
                flushLi();
                const closing = listStack.pop();
                result.push(`</${closing.type}>`);
                listStack.push({ type: listType, indent: indent });
                result.push(`<${listType}>`);
              } else if (listStack.length === 0 || listStack[listStack.length - 1].indent < indent) {
                listStack.push({ type: listType, indent: indent });
                result.push(`<${listType}>`);
              }
            } else if (lastList.type !== listType) {
              // 同层级但类型不同，关闭旧列表，开启新列表
              flushLi();
              const closing = listStack.pop();
              result.push(`</${closing.type}>`);
              listStack.push({ type: listType, indent: indent });
              result.push(`<${listType}>`);
            }
          }

          // 开始新的列表项
          currentLiContent = [content];
          currentLiIndent = indent;
        } else if (currentLiContent !== null) {
          // 当前在列表项中，检查是否是续行
          const lineIndent = line.match(/^(\s*)/)?.[1].length || 0;

          // 如果是空行或缩进足够的行，视为列表项的续行
          if (trimmed === '') {
            // 检查下一行是否继续当前列表
            const nextLine = lines[i + 1];
            if (nextLine) {
              const nextMatch = isListItem(nextLine);
              const nextIndent = nextLine.match(/^(\s*)/)?.[1].length || 0;

              if (!nextMatch || nextIndent <= currentLiIndent) {
                // 列表项结束
                flushLi();
              } else {
                // 继续列表项，保留空行
                currentLiContent.push('');
              }
            } else {
              flushLi();
            }
          } else if (lineIndent > currentLiIndent || (trimmed.startsWith('>') && lineIndent >= currentLiIndent)) {
            // 缩进更多，是续行；引用块允许与列表项标记同缩进，避免子列表后的引用块截断外层列表
            currentLiContent.push(line.trim());
          } else if (!isListItem(line)) {
            // 不是列表项且缩进不够，列表结束
            flushLi();
            // 关闭所有列表
            while (listStack.length > 0) {
              const closing = listStack.pop();
              result.push(`</${closing.type}>`);
            }
            result.push(line);
          } else {
            // 是新的列表项，flushLi 会在下一轮处理
            flushLi();
          }
        } else if (trimmed === '' && listStack.length > 0) {
          // 空行，检查下一行是否继续列表
          const nextLine = lines[i + 1];
          if (nextLine) {
            if (!isListItem(nextLine)) {
              // 列表结束
              flushLi();
              while (listStack.length > 0) {
                const closing = listStack.pop();
                result.push(`</${closing.type}>`);
              }
              result.push('');
            } else {
              result.push('');
            }
          } else {
            // 文件结束
            flushLi();
            while (listStack.length > 0) {
              const closing = listStack.pop();
              result.push(`</${closing.type}>`);
            }
            result.push('');
          }
        } else {
          result.push(line);
        }
      }

      // 关闭所有未关闭的内容
      flushLi();
      while (listStack.length > 0) {
        const closing = listStack.pop();
        result.push(`</${closing.type}>`);
      }

      return result.join('\n');
    }

    html = parseLists(html);

    // 处理分隔线
    html = html.replace(/^---$/gim, '<hr>');
    html = html.replace(/^\*\*\*$/gim, '<hr>');
    html = html.replace(/^___$/gim, '<hr>');

    // 处理段落（在行之间添加 p 标签）
    const lines = html.split('\n');
    const result = [];
    let inParagraph = false;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();

      if (!line) {
        if (inParagraph) {
          result.push('</p>');
          inParagraph = false;
        }
        continue;
      }

      // 如果行已经是块级元素，不包裹在 p 中
      if (line.match(/^<(h[1-6]|ul|ol|li|blockquote|pre|hr)/)) {
        if (inParagraph) {
          result.push('</p>');
          inParagraph = false;
        }
        result.push(line);
      } else if (line.match(/<\/(h[1-6]|ul|ol|li|blockquote|pre|hr)>$/)) {
        result.push(line);
        inParagraph = false;
      } else {
        if (!inParagraph) {
          result.push('<p>');
          inParagraph = true;
        }
        result.push(line);
      }
    }

    if (inParagraph) {
      result.push('</p>');
    }

    html = result.join('\n');

    // 替换代码块占位符
    html = html.replace(/\x00CODE(\d+)\x00/g, function(match, index) {
      return codeBlocks[parseInt(index)];
    });

    // 替换表格占位符
    html = html.replace(/\x00TABLE(\d+)\x00/g, function(match, index) {
      return tables[parseInt(index)];
    });

    // 替换行内代码占位符
    html = html.replace(/\x00INLINE(\d+)\x00/g, function(match, index) {
      return inlineCodes[parseInt(index)];
    });

    // 替换独立引用块占位符
    html = html.replace(/\x00BLOCKQUOTE(\d+)\x00/g, function(match, index) {
      return blockquotes[parseInt(index)];
    });

    // 恢复转义字符
    html = restoreEscapes(html);

    return html;
  }

  // 配置选项
  let globalOptions = {
    breaks: false,
    gfm: true,
    headerIds: false,
    mangle: false
  };

  // 暴露 API
  const marked = {
    parse: function(text, options) {
      return parseMarkdown(text);
    },
    parseInline: function(text) {
      return parseMarkdown(text);
    },
    setOptions: function(options) {
      if (options && typeof options === 'object') {
        Object.assign(globalOptions, options);
      }
      return marked;
    },
    getDefaults: function() {
      return Object.assign({}, globalOptions);
    }
  };

  // 导出
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = marked;
  } else if (typeof define === 'function' && define.amd) {
    define(function() { return marked; });
  } else {
    global.marked = marked;
  }

})(typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : this);
